import * as THREE from 'three';
import type { App, Feature, FrameContext } from '../app';
import { GROUP_ALL, GROUP_DEPTH, GROUP_HAND, RAPIER, interactionGroups } from '../physics';
import type { Room } from './room';

/** 深度を読み出す格子の大きさ。この数だけ点を取る。 */
const COLUMNS = 32;
const ROWS = 32;
const POINT_COUNT = COLUMNS * ROWS;
/** 深度を読み出す間隔 (秒)。読み出しが終わるまでは次を始めない。 */
const INTERVAL = 0.1;
/** この範囲の距離 (m) の点だけを使う。近すぎる所と遠い所は誤差が大きい。 */
const MIN_RANGE = 0.25;
const MAX_RANGE = 4;
/** 深度を 16 bit に詰めるときの最大値 (m) */
const ENCODE_RANGE = 8;
/** 部屋の当たり判定 (床・壁・机など) からこの距離 (m) 以内の点は、もう当たり判定があるので使わない */
const ROOM_MARGIN = 0.06;
/** 手のこの範囲 (m) の点は使わない。手は HandColliders が関節ごとに当たり判定を持っている。 */
const HAND_MARGIN = 0.15;
/**
 * 隣り合う 2 点の「距離の逆数」の差が、この割合以下なら、ほぼ同じ距離なので、そのまま面でつなぐ。
 * これを超える差は、斜めの面か、物の輪郭 (手前の物と奥の壁の境目) のどちらか。
 */
const SMOOTH_STEP = 0.05;
/**
 * 斜めの面と輪郭の見分け方。平らな面では、距離の逆数が格子に沿って一定の割合で変わる。
 * 前後の点との差も同じくらい (この割合までのずれ) なら、斜めに続く面とみなしてつなぐ。
 * 輪郭では、そこだけ差が跳ぶので、前後の差とは揃わない。
 */
const SLOPE_TOLERANCE = 0.5;
const DEPTH_FRICTION = 0.8;
const DEPTH_RESTITUTION = 0.4;
const DEBUG_COLOR = 0xffa040;

const VERTEX_SHADER = /* glsl */ `
varying vec2 vUv;
void main() {
  vUv = uv;
  gl_Position = vec4(position.xy, 0.0, 1.0);
}`;

/** 深度テクスチャの値を距離 (m) に直し、16 bit に詰めて R と G に書く。 */
const FRAGMENT_SHADER = /* glsl */ `
uniform sampler2DArray depthTexture;
uniform float layer;
// 射影行列の z の係数。深度バッファの値を、カメラからの距離 (m) に直すのに使う。
uniform vec2 projection;
varying vec2 vUv;
void main() {
  // 隣の画素と混ぜると、物の輪郭に存在しない距離ができるので、補間せずに 1 画素だけ読む。
  ivec2 size = textureSize(depthTexture, 0).xy;
  float depth = texelFetch(depthTexture, ivec3(vUv * vec2(size), int(layer)), 0).r;
  float meters = projection.y / min(depth * 2.0 - 1.0 + projection.x, -1e-6);
  float value = floor(clamp(meters / ${ENCODE_RANGE.toFixed(1)}, 0.0, 1.0) * 65535.0 + 0.5);
  float high = floor(value / 256.0);
  gl_FragColor = vec4(high / 255.0, (value - high * 256.0) / 255.0, 0.0, 1.0);
}`;

/** 深度を読み出したときの、深度の視点。読み出しは数フレーム後に終わるので、頼んだ時点のものを覚えておく。 */
interface Snapshot {
  /** 深度の視点 → ワールド */
  world: THREE.Matrix4;
  /** クリップ空間 → 深度の視点 */
  inverseProjection: THREE.Matrix4;
  session: number;
}

const _point = new THREE.Vector3();
const IDENTITY = { x: 0, y: 0, z: 0, w: 1 };
const EMPTY_VERTICES = new Float32Array(0);
const EMPTY_INDICES = new Uint32Array(0);
/** 部屋の当たり判定だけを探す問い合わせ。手と深度の面は除く。 */
const ROOM_ONLY = interactionGroups(GROUP_ALL, GROUP_ALL & ~(GROUP_HAND | GROUP_DEPTH));

/**
 * 深度センサー (depth-sensing) の値から、現実の物の当たり判定をリアルタイムに作る。
 *
 * 部屋の当たり判定 (Room) は事前のスキャン結果なので、後から動かした椅子や、人、
 * 置いた荷物には当たらない。深度は毎フレーム届くので、それを格子状の点の集まりにして、
 * 隣り合う点を三角形で結んだ面を、当たり判定として作り直す。
 * (点ごとに球を置く方式は、球の間、特に斜めから見た床や机の上で、物がすり抜けた。)
 *
 * 深度は GPU のテクスチャでしか受け取れないので、小さなレンダーターゲットへ縮小して書き出し、
 * 非同期に CPU へ読み出す。読み出しを待つ間も描画は止まらない。
 */
export class DepthColliders implements Feature {
  readonly name = 'depthColliders';
  enabled = true;
  /** いまの当たり判定の三角形の数 */
  count = 0;

  private readonly target = new THREE.WebGLRenderTarget(COLUMNS, ROWS, {
    type: THREE.UnsignedByteType,
    format: THREE.RGBAFormat,
    minFilter: THREE.NearestFilter,
    magFilter: THREE.NearestFilter,
    depthBuffer: false,
  });
  private readonly material = new THREE.ShaderMaterial({
    vertexShader: VERTEX_SHADER,
    fragmentShader: FRAGMENT_SHADER,
    uniforms: {
      depthTexture: { value: null as THREE.Texture | null },
      layer: { value: 0 },
      projection: { value: new THREE.Vector2(-1, -0.1) },
    },
    depthTest: false,
    depthWrite: false,
    blending: THREE.NoBlending,
  });
  private readonly quadScene = new THREE.Scene();
  private readonly quadCamera = new THREE.OrthographicCamera();
  private readonly pixels = new Uint8Array(POINT_COUNT * 4);
  /** 格子の点のワールド座標と、使える点かどうか */
  private readonly points = new Float32Array(POINT_COUNT * 3);
  private readonly valid = new Uint8Array(POINT_COUNT);
  /** 格子の点の、距離 (m) の逆数。面の続き具合を調べるのに使う。 */
  private readonly inverse = new Float32Array(POINT_COUNT);
  /** 格子の点 → 当たり判定の頂点の番号。使わない点は -1。 */
  private readonly vertexOf = new Int32Array(POINT_COUNT);
  private collider: RAPIER.Collider | null = null;
  private readonly debug: THREE.Mesh<THREE.BufferGeometry, THREE.MeshBasicMaterial>;
  private pending = false;
  private lastRequest = -Infinity;
  /** セッションごとに進める番号。終了後に届いた読み出し結果を捨てるのに使う。 */
  private session = 0;

  constructor(
    private readonly app: App,
    private readonly room: Room,
  ) {
    const quad = new THREE.Mesh(new THREE.PlaneGeometry(2, 2), this.material);
    quad.frustumCulled = false;
    this.quadScene.add(quad);

    const debugMaterial = new THREE.MeshBasicMaterial({
      color: DEBUG_COLOR,
      wireframe: true,
      transparent: true,
      opacity: 0.5,
      depthWrite: false,
    });
    // 面は現実の面にぴったり重なっているので、遮蔽すると見えなくなる。
    debugMaterial.userData.occlusion = 'ignore';
    this.debug = new THREE.Mesh(new THREE.BufferGeometry(), debugMaterial);
    this.debug.frustumCulled = false;
    app.scene.add(this.debug);

    app.menu.addToggle(
      '深度で当たる',
      () => this.enabled,
      (value) => (this.enabled = value),
    );
  }

  start(): void {
    this.session++;
    this.pending = false;
    this.lastRequest = -Infinity;
  }

  end(): void {
    this.session++;
    this.setMesh(EMPTY_VERTICES, EMPTY_INDICES);
  }

  update(ctx: FrameContext): void {
    this.debug.visible = this.room.visible;
    if (!this.enabled) {
      if (this.count > 0) this.setMesh(EMPTY_VERTICES, EMPTY_INDICES);
      return;
    }
    if (this.pending || ctx.time - this.lastRequest < INTERVAL) return;
    const snapshot = this.render(ctx);
    if (!snapshot) return;
    this.lastRequest = ctx.time;
    this.pending = true;
    this.app.renderer
      .readRenderTargetPixelsAsync(this.target, 0, 0, COLUMNS, ROWS, this.pixels)
      .then(() => {
        if (snapshot.session === this.session && this.enabled) this.build(snapshot);
      })
      .catch((error: unknown) => console.warn('[depthColliders] 深度の読み出しに失敗しました', error))
      .finally(() => {
        if (snapshot.session === this.session) this.pending = false;
      });
  }

  /** 左目の深度を、距離 (m) にしてレンダーターゲットへ書く。 */
  private render(ctx: FrameContext): Snapshot | null {
    const xr = this.app.renderer.xr;
    const texture = xr.getDepthTexture();
    const view = ctx.frame.getViewerPose(ctx.refSpace)?.views[0];
    if (!texture || !view) return null;
    // 深度は描画の視点とは別の視点 (深度センサーの視点) で取られていることがあり、
    // そのときは深度の情報に視点の姿勢と射影が付いてくる。無ければ描画の視点と同じとみなす。
    const info = xr.getBinding().getDepthInformation(view);
    const projection = info?.projectionMatrix ?? view.projectionMatrix;
    const transform = info?.transform ?? view.transform;

    const uniforms = this.material.uniforms;
    uniforms.depthTexture.value = texture;
    uniforms.layer.value = info?.imageIndex ?? 0;
    uniforms.projection.value.set(projection[10], projection[14]);

    const renderer = this.app.renderer;
    const previousTarget = renderer.getRenderTarget();
    const previousXr = xr.enabled;
    try {
      // XR セッション中の renderer は XR のカメラで描くので、一時的に外す。
      xr.enabled = false;
      renderer.setRenderTarget(this.target);
      renderer.render(this.quadScene, this.quadCamera);
    } finally {
      renderer.setRenderTarget(previousTarget);
      xr.enabled = previousXr;
    }

    return {
      world: new THREE.Matrix4().fromArray(transform.matrix),
      inverseProjection: new THREE.Matrix4().fromArray(projection).invert(),
      session: this.session,
    };
  }

  /** 読み出した距離を格子の点にし、隣り合う点を三角形で結んで、当たり判定を作り直す。 */
  private build(snapshot: Snapshot): void {
    const world = this.app.physics.world;
    const hands = this.app.input.hands.filter((hand) => hand.tracked);
    const { points, valid } = this;
    for (let index = 0; index < POINT_COUNT; index++) {
      valid[index] = 0;
      const meters = ((this.pixels[index * 4] * 256 + this.pixels[index * 4 + 1]) / 65535) * ENCODE_RANGE;
      if (meters < MIN_RANGE || meters > MAX_RANGE) continue;
      this.inverse[index] = 1 / meters;

      // 格子の中心を、深度の視点の座標を経てワールド座標にする。
      const x = ((index % COLUMNS) + 0.5) / COLUMNS;
      const y = (Math.floor(index / COLUMNS) + 0.5) / ROWS;
      _point.set(x * 2 - 1, y * 2 - 1, -1).applyMatrix4(snapshot.inverseProjection);
      _point.multiplyScalar(meters / -_point.z).applyMatrix4(snapshot.world);

      if (hands.some((hand) => hand.grabPosition.distanceTo(_point) < HAND_MARGIN)) continue;
      const nearest = world.projectPoint(_point, true, RAPIER.QueryFilterFlags.ONLY_FIXED, ROOM_ONLY);
      if (nearest && (nearest.isInside || _point.distanceTo(nearest.point) < ROOM_MARGIN)) continue;
      _point.toArray(points, index * 3);
      valid[index] = 1;
    }

    // 格子の 1 マスを 2 つの三角形にする。3 辺とも面として続いているものだけを張る。
    const triangles: number[] = [];
    for (let row = 0; row < ROWS - 1; row++) {
      for (let column = 0; column < COLUMNS - 1; column++) {
        const right = this.continuous(column, row, 1, 0);
        const up = this.continuous(column, row, 0, 1);
        const diagonal = this.continuous(column + 1, row, -1, 1);
        const top = this.continuous(column, row + 1, 1, 0);
        const side = this.continuous(column + 1, row, 0, 1);
        const i = row * COLUMNS + column;
        if (right && up && diagonal) triangles.push(i, i + 1, i + COLUMNS);
        if (side && top && diagonal) triangles.push(i + 1, i + COLUMNS + 1, i + COLUMNS);
      }
    }

    // 三角形に使われた点だけを、当たり判定の頂点として詰めて並べる。
    this.vertexOf.fill(-1);
    const vertices: number[] = [];
    const indices = new Uint32Array(triangles.length);
    triangles.forEach((index, n) => {
      if (this.vertexOf[index] < 0) {
        this.vertexOf[index] = vertices.length / 3;
        vertices.push(points[index * 3], points[index * 3 + 1], points[index * 3 + 2]);
      }
      indices[n] = this.vertexOf[index];
    });
    this.setMesh(new Float32Array(vertices), indices);
    this.wakeTouching();
  }

  /**
   * 格子の点 (column, row) と、そこから (dc, dr) 進んだ点が、同じ面の続きかどうか。
   *
   * 平らな面では、距離の逆数が格子に沿って一定の割合で変わる (透視投影の性質)。
   * なので、浅い角度で見た机や、傾いた背もたれのように距離が大きく変わる所でも、
   * 前後の点との差と揃っていれば面の続きと分かる。輪郭では、そこだけ差が跳ぶ。
   */
  private continuous(column: number, row: number, dc: number, dr: number): boolean {
    const a = this.indexAt(column, row);
    const b = this.indexAt(column + dc, row + dr);
    if (a < 0 || b < 0) return false;
    const w = this.inverse;
    const step = w[b] - w[a];
    if (Math.abs(step) <= SMOOTH_STEP * Math.max(w[a], w[b])) return true;
    const before = this.indexAt(column - dc, row - dr);
    const after = this.indexAt(column + 2 * dc, row + 2 * dr);
    return (
      (before >= 0 && Math.abs(w[a] - w[before] - step) <= SLOPE_TOLERANCE * Math.abs(step)) ||
      (after >= 0 && Math.abs(w[after] - w[b] - step) <= SLOPE_TOLERANCE * Math.abs(step))
    );
  }

  /** 格子の点の番号。格子の外か、使えない点なら -1。 */
  private indexAt(column: number, row: number): number {
    if (column < 0 || column >= COLUMNS || row < 0 || row >= ROWS) return -1;
    const index = row * COLUMNS + column;
    return this.valid[index] ? index : -1;
  }

  /** 当たり判定と表示を、この三角形の集まりに置き換える。空なら当たり判定を消す。 */
  private setMesh(vertices: Float32Array, indices: Uint32Array): void {
    const world = this.app.physics.world;
    if (this.collider) world.removeCollider(this.collider, false);
    this.collider =
      indices.length > 0
        ? world.createCollider(
            RAPIER.ColliderDesc.trimesh(vertices, indices)
              .setFriction(DEPTH_FRICTION)
              .setRestitution(DEPTH_RESTITUTION)
              .setCollisionGroups(interactionGroups(GROUP_DEPTH, GROUP_ALL & ~(GROUP_HAND | GROUP_DEPTH))),
          )
        : null;
    this.count = indices.length / 3;

    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute('position', new THREE.BufferAttribute(vertices, 3));
    geometry.setIndex(new THREE.BufferAttribute(indices, 1));
    this.debug.geometry.dispose();
    this.debug.geometry = geometry;
  }

  /**
   * 眠っている (止まって計算を省かれている) 物は、剛体を持たない当たり判定が動いてきても起きない。
   * 現実の物が押しのけられるよう、重なった物は起こす。
   */
  private wakeTouching(): void {
    const collider = this.collider;
    if (!collider) return;
    this.app.physics.world.intersectionsWithShape(
      collider.translation(),
      IDENTITY,
      collider.shape,
      (other) => {
        const body = other.parent();
        if (body?.isSleeping()) body.wakeUp();
        return true;
      },
      RAPIER.QueryFilterFlags.ONLY_DYNAMIC,
    );
  }
}
import * as THREE from 'three';
import type { App, Feature } from '../app';

/**
 * 現実の面を、実際より奥にあるものとして扱う量。距離 d (m) の面を d * (1 + RELATIVE) + ABSOLUTE に置く。
 * 深度センサーの値は毎フレーム揺れ、遠いほど誤差が大きい。そのままだと、床や壁に接している
 * 仮想物体が現実の面と前後を取り合ってチラつくので、この分だけ仮想物体を優先する。
 * 大きくするほどチラつきは減るが、現実の物のすぐ後ろにある仮想物体が隠れなくなる。
 */
const ABSOLUTE_BIAS = 0.02;
const RELATIVE_BIAS = 0.03;
/** 「くっきり」方式で周囲の深度も見るときの、中心からの距離 (画面のピクセル数) */
const TAP_RADIUS = 4;
/**
 * 「ぼかし」方式で深度を調べる範囲の半径 (画面のピクセル数)。
 * 広いほど深度の揺れが平均されてチラつきが減るが、輪郭のぼけも広がる。
 */
const SOFT_RADIUS = 12;
/**
 * 「ぼかし」方式で、仮想物体が現実の面のどれだけ奥にあれば完全に隠れるか。
 * 距離 d (m) で SOFT_FADE_ABSOLUTE + d * SOFT_FADE_RELATIVE (m)。この間は徐々に薄くなる。
 */
const SOFT_FADE_ABSOLUTE = 0.04;
const SOFT_FADE_RELATIVE = 0.04;

/** マテリアルごとの遮蔽の扱い。material.userData.occlusion で指定する。 */
export type OcclusionMode =
  /** 現実の物に隠れる (既定) */
  | 'soft'
  /** 隠れない。ポータルの中の世界など、現実の面より奥に描きたいもの。 */
  | 'ignore'
  /** 隠れる所を描かない。半透明にできない、ステンシルへの書き込み用。 */
  | 'mask';

const VERTEX_SHADER = /* glsl */ `
void main() {
  gl_Position = vec4(position, 1.0);
}`;

const FRAGMENT_SHADER = /* glsl */ `
uniform sampler2DArray depthColor;
uniform float depthWidth;
uniform float depthHeight;
// 射影行列の z の係数。深度バッファの値と、カメラからの距離 (m) を相互に変換するのに使う。
uniform float projectionA;
uniform float projectionB;

float sampleDepth(vec2 pixel) {
  vec2 coord = pixel / vec2(depthWidth, depthHeight);
  // 左右の目の映像は横に並んでいて、深度テクスチャは目ごとに層が分かれている。
  float layer = step(1.0, coord.x);
  return texture(depthColor, vec3(coord.x - layer, coord.y, layer)).r;
}

void main() {
  vec2 pixel = gl_FragCoord.xy;
  // 周囲も調べて、いちばん奥の値を使う。現実の物の輪郭では深度が手前と奥を行き来するので、
  // 奥側に寄せておくと、輪郭のチラつきが「仮想物体が少しはみ出て見える」程度で済む。
  float depth = sampleDepth(pixel);
  depth = max(depth, sampleDepth(pixel + vec2(TAP_RADIUS, TAP_RADIUS)));
  depth = max(depth, sampleDepth(pixel + vec2(-TAP_RADIUS, TAP_RADIUS)));
  depth = max(depth, sampleDepth(pixel + vec2(TAP_RADIUS, -TAP_RADIUS)));
  depth = max(depth, sampleDepth(pixel + vec2(-TAP_RADIUS, -TAP_RADIUS)));

  // 深度バッファの値 → 距離 (m) → 奥へずらす → 深度バッファの値
  float meters = projectionB / min(depth * 2.0 - 1.0 + projectionA, -1e-6);
  meters = meters * (1.0 + RELATIVE_BIAS) + ABSOLUTE_BIAS;
  gl_FragDepth = clamp((projectionB / meters - projectionA) * 0.5 + 0.5, 0.0, 1.0);
}`;

/** 「ぼかし」方式で、各マテリアルのフラグメントシェーダーの先頭に足す宣言 */
const SOFT_DECLARATIONS = /* glsl */ `
uniform sampler2DArray xrDepthTexture;
uniform vec2 xrDepthSize;
uniform vec2 xrProjection;
uniform float xrOcclusionStrength;

float xrMeters(float depth) {
  return xrProjection.y / min(depth * 2.0 - 1.0 + xrProjection.x, -1e-6);
}

// この画素の位置で、仮想物体が現実の面より手前にあれば 1、十分に奥なら 0。
float xrTap(vec2 pixel, float fragmentMeters, float fade) {
  vec2 coord = pixel / xrDepthSize;
  float layer = step(1.0, coord.x);
  float depth = texture(xrDepthTexture, vec3(coord.x - layer, coord.y, layer)).r;
  float realMeters = xrMeters(depth) * (1.0 + ${RELATIVE_BIAS.toFixed(4)}) + ${ABSOLUTE_BIAS.toFixed(4)};
  return clamp((realMeters - fragmentMeters) / fade + 1.0, 0.0, 1.0);
}

// 周囲の複数の点で前後を判定し、その平均を「見えている割合」とする。
// 深度そのものを平均すると、輪郭で手前と奥の中間という存在しない距離ができてしまうので、
// 判定の結果のほうを平均する。
float xrOcclusionVisibility() {
  if (xrOcclusionStrength < 0.5) return 1.0;
  float fragmentMeters = xrMeters(gl_FragCoord.z);
  float fade = ${SOFT_FADE_ABSOLUTE.toFixed(4)} + ${SOFT_FADE_RELATIVE.toFixed(4)} * fragmentMeters;
  vec2 pixel = gl_FragCoord.xy;
  const float r = ${SOFT_RADIUS.toFixed(1)};
  const float d = r * 0.7071;
  float sum = xrTap(pixel, fragmentMeters, fade) * 2.0;
  sum += xrTap(pixel + vec2(r, 0.0), fragmentMeters, fade);
  sum += xrTap(pixel + vec2(-r, 0.0), fragmentMeters, fade);
  sum += xrTap(pixel + vec2(0.0, r), fragmentMeters, fade);
  sum += xrTap(pixel + vec2(0.0, -r), fragmentMeters, fade);
  sum += xrTap(pixel + vec2(d, d), fragmentMeters, fade);
  sum += xrTap(pixel + vec2(-d, d), fragmentMeters, fade);
  sum += xrTap(pixel + vec2(d, -d), fragmentMeters, fade);
  sum += xrTap(pixel + vec2(-d, -d), fragmentMeters, fade);
  sum += xrTap(pixel + vec2(r * 0.5, 0.0), fragmentMeters, fade);
  sum += xrTap(pixel + vec2(-r * 0.5, 0.0), fragmentMeters, fade);
  sum += xrTap(pixel + vec2(0.0, r * 0.5), fragmentMeters, fade);
  sum += xrTap(pixel + vec2(0.0, -r * 0.5), fragmentMeters, fade);
  return sum / 14.0;
}
`;

/** main() の最後に足す処理 */
const SOFT_APPLY: Record<Exclude<OcclusionMode, 'ignore'>, string> = {
  // パススルー映像との合成は、フレームバッファのアルファ (乗算済み) で行われる。
  // 不透明なマテリアルはブレンドしないので、色とアルファの両方を下げて現実を透かす。
  // 半透明なマテリアルは、アルファを下げればブレンドの結果として薄くなる。
  soft: /* glsl */ `
  float xrVisible = xrOcclusionVisibility();
  if (xrVisible < 0.004) discard;
  #ifdef OPAQUE
    gl_FragColor *= xrVisible;
  #else
    gl_FragColor.a *= xrVisible;
  #endif
`,
  mask: /* glsl */ `
  if (xrOcclusionVisibility() < 0.5) discard;
`,
};

/** 全マテリアルで共有する uniform。値を書き換えると、すべてのマテリアルに反映される。 */
const softUniforms = {
  xrDepthTexture: { value: null as THREE.Texture | null },
  xrDepthSize: { value: new THREE.Vector2(1, 1) },
  xrProjection: { value: new THREE.Vector2(-1, -0.1) },
  xrOcclusionStrength: { value: 0 },
};

function occlusionMode(material: THREE.Material): OcclusionMode {
  const flags = material as THREE.Material & {
    isShaderMaterial?: boolean;
    isMeshDepthMaterial?: boolean;
    isMeshDistanceMaterial?: boolean;
  };
  // 自前のシェーダーと、影の計算用のマテリアルには手を入れない。
  if (flags.isShaderMaterial || flags.isMeshDepthMaterial || flags.isMeshDistanceMaterial) return 'ignore';
  // 深度テストをしないもの (メニュー、照準、ラベル) は、常に見せたいものなので隠さない。
  if (!material.depthTest) return 'ignore';
  return (material.userData.occlusion as OcclusionMode | undefined) ?? 'soft';
}

/**
 * 遮蔽なしで描く。XR の画面以外 (写真用のレンダーターゲットなど) へ描くときに使う。
 * 「ぼかし」方式は XR の画面の画素位置から深度を引くので、別の視点の描画には使えない。
 */
export function withoutOcclusion(render: () => void): void {
  const strength = softUniforms.xrOcclusionStrength.value;
  softUniforms.xrOcclusionStrength.value = 0;
  try {
    render();
  } finally {
    softUniforms.xrOcclusionStrength.value = strength;
  }
}

let installed = false;

/**
 * 「ぼかし」方式の遮蔽を、three.js の標準マテリアルすべてに組み込む。
 *
 * 画素ごとに薄くするには、各マテリアルのフラグメントシェーダーで現実の深度と比べる必要がある。
 * マテリアルを作る場所ごとに設定して回る代わりに、Material の既定のフック (onBeforeCompile) を
 * 差し替えて、シェーダーのコンパイル時に一括で処理を足している。
 */
function installSoftOcclusion(): void {
  if (installed) return;
  installed = true;
  // 同じ種類のマテリアルでも、遮蔽の扱いが違えば別のシェーダーになるようにする。
  THREE.Material.prototype.customProgramCacheKey = function (this: THREE.Material): string {
    return `xr-occlusion:${occlusionMode(this)}`;
  };
  THREE.Material.prototype.onBeforeCompile = function (this: THREE.Material, shader): void {
    const mode = occlusionMode(this);
    if (mode === 'ignore') return;
    const end = shader.fragmentShader.lastIndexOf('}');
    if (end < 0) return;
    Object.assign(shader.uniforms, softUniforms);
    shader.fragmentShader =
      SOFT_DECLARATIONS + shader.fragmentShader.slice(0, end) + SOFT_APPLY[mode] + shader.fragmentShader.slice(end);
  };
}

/**
 * 現実の物や自分の手で、仮想物体を隠す (depth-sensing)。方式が 2 つある。
 *
 * くっきり: 現実の深度を、仮想物体より先に深度バッファへ書いておく。three.js 標準の仕組みで、
 *   WebXRManager が毎フレーム深度テクスチャを受け取り、それを書くだけのメッシュを最初に描く。
 *   以降の仮想物体は、現実の面より奥にある画素が深度テストで落ちる。
 *   ここではそのメッシュのシェーダーを、センサーの誤差のぶん奥へずらして書くものに差し替えている。
 *   画素ごとに「見える / 見えない」の二択なので、深度が揺れる所ではチラつく。
 *
 * ぼかし: 深度バッファには書かず、各マテリアルのシェーダーの中で現実の深度と比べ、
 *   周囲の判定の平均に応じて薄くする。輪郭がなめらかになり、深度の揺れは濃淡の揺れに和らぐ。
 *   そのぶん、仮想物体を描く画素ごとに深度を何度も読むので重い。
 */
export class Occlusion implements Feature {
  readonly name = 'occlusion';
  enabled = true;
  /** true なら「ぼかし」、false なら「くっきり」 */
  soft = true;
  /** 深度データが届いているか */
  active = false;

  private patched: THREE.Mesh | null = null;
  private material: THREE.ShaderMaterial | null = null;

  constructor(private readonly app: App) {
    installSoftOcclusion();
    app.menu.addToggle(
      '遮蔽',
      () => this.enabled,
      (value) => (this.enabled = value),
    );
    app.menu.addToggle(
      '遮蔽をぼかす',
      () => this.soft,
      (value) => (this.soft = value),
    );
  }

  update(): void {
    const xr = this.app.renderer.xr;
    // 深度データが一度も届いていない間は null。
    const mesh = xr.getDepthSensingMesh();
    const texture = xr.getDepthTexture();
    this.active = mesh !== null && texture !== null;
    softUniforms.xrDepthTexture.value = texture;
    softUniforms.xrOcclusionStrength.value = this.active && this.enabled && this.soft ? 1 : 0;
    if (!mesh) return;
    mesh.visible = this.enabled && !this.soft;
    if (mesh !== this.patched) this.patch(mesh);

    // 深度テクスチャは描画と同じ near / far で作られている (three.js がカメラ側を合わせる)。
    // 両目で共通なので、片目の射影行列から係数を取ればよい。
    const eye = xr.getCamera().cameras[0];
    if (!eye || !this.material) return;
    const a = eye.projectionMatrix.elements[10];
    const b = eye.projectionMatrix.elements[14];
    this.material.uniforms.projectionA.value = a;
    this.material.uniforms.projectionB.value = b;
    softUniforms.xrProjection.value.set(a, b);
    softUniforms.xrDepthSize.value.set(eye.viewport.z, eye.viewport.w);
  }

  end(): void {
    this.active = false;
    this.patched = null;
    this.material?.dispose();
    this.material = null;
    softUniforms.xrDepthTexture.value = null;
    softUniforms.xrOcclusionStrength.value = 0;
  }

  /** three.js が作ったメッシュのマテリアルを差し替える。テクスチャなどの値は元のものを引き継ぐ。 */
  private patch(mesh: THREE.Mesh): void {
    const original = mesh.material as THREE.ShaderMaterial;
    this.material?.dispose();
    this.material = new THREE.ShaderMaterial({
      vertexShader: VERTEX_SHADER,
      fragmentShader: FRAGMENT_SHADER,
      defines: {
        ABSOLUTE_BIAS: ABSOLUTE_BIAS.toFixed(4),
        RELATIVE_BIAS: RELATIVE_BIAS.toFixed(4),
        TAP_RADIUS: TAP_RADIUS.toFixed(1),
      },
      uniforms: {
        depthColor: original.uniforms.depthColor,
        depthWidth: original.uniforms.depthWidth,
        depthHeight: original.uniforms.depthHeight,
        projectionA: { value: -1 },
        projectionB: { value: -0.1 },
      },
    });
    mesh.material = this.material;
    original.dispose();
    this.patched = mesh;
  }
}
