260	        const i = row * COLUMNS + column;
261	        if (right && up && diagonal) triangles.push(i, i + 1, i + COLUMNS);
262	        if (side && top && diagonal) triangles.push(i + 1, i + COLUMNS + 1, i + COLUMNS);
263	      }
264	    }
265	
266	    // 三角形に使われた点だけを、当たり判定の頂点として詰めて並べる。
267	    this.vertexOf.fill(-1);
268	    const vertices: number[] = [];
269	    const indices = new Uint32Array(triangles.length);
270	    triangles.forEach((index, n) => {
271	      if (this.vertexOf[index] < 0) {
272	        this.vertexOf[index] = vertices.length / 3;
273	        vertices.push(points[index * 3], points[index * 3 + 1], points[index * 3 + 2]);
274	      }
275	      indices[n] = this.vertexOf[index];
276	    });
277	    this.setMesh(new Float32Array(vertices), indices);
278	    this.wakeTouching();
279	  }
280	
281	  /**
282	   * 格子の点 (column, row) と、そこから (dc, dr) 進んだ点が、同じ面の続きかどうか。
283	   *
284	   * 平らな面では、距離の逆数が格子に沿って一定の割合で変わる (透視投影の性質)。
285	   * なので、浅い角度で見た机や、傾いた背もたれのように距離が大きく変わる所でも、
286	   * 前後の点との差と揃っていれば面の続きと分かる。輪郭では、そこだけ差が跳ぶ。
287	   */
288	  private continuous(column: number, row: number, dc: number, dr: number): boolean {
289	    const a = this.indexAt(column, row);
290	    const b = this.indexAt(column + dc, row + dr);
291	    if (a < 0 || b < 0) return false;
292	    const w = this.inverse;
293	    const step = w[b] - w[a];
294	    if (Math.abs(step) <= SMOOTH_STEP * Math.max(w[a], w[b])) return true;
295	    const before = this.indexAt(column - dc, row - dr);
296	    const after = this.indexAt(column + 2 * dc, row + 2 * dr);
297	    return (
298	      (before >= 0 && Math.abs(w[a] - w[before] - step) <= SLOPE_TOLERANCE * Math.abs(step)) ||
299	      (after >= 0 && Math.abs(w[after] - w[b] - step) <= SLOPE_TOLERANCE * Math.abs(step))
300	    );
301	  }
302	
303	  /** 格子の点の番号。格子の外か、使えない点なら -1。 */
304	  private indexAt(column: number, row: number): number {
305	    if (column < 0 || column >= COLUMNS || row < 0 || row >= ROWS) return -1;
306	    const index = row * COLUMNS + column;
307	    return this.valid[index] ? index : -1;
308	  }
309	
310	  /** 当たり判定と表示を、この三角形の集まりに置き換える。空なら当たり判定を消す。 */
311	  private setMesh(vertices: Float32Array, indices: Uint32Array): void {
312	    const world = this.app.physics.world;
313	    if (this.collider) world.removeCollider(this.collider, false);
314	    this.collider =
315	      indices.length > 0
316	        ? world.createCollider(
317	            RAPIER.ColliderDesc.trimesh(vertices, indices)
318	              .setFriction(DEPTH_FRICTION)
319	              .setRestitution(DEPTH_RESTITUTION)
320	              .setCollisionGroups(interactionGroups(GROUP_DEPTH, GROUP_ALL & ~(GROUP_HAND | GROUP_DEPTH))),
321	          )
322	        : null;
323	    this.count = indices.length / 3;
324	
325	    const geometry = new THREE.BufferGeometry();
326	    geometry.setAttribute('position', new THREE.BufferAttribute(vertices, 3));
327	    geometry.setIndex(new THREE.BufferAttribute(indices, 1));
328	    this.debug.geometry.dispose();
329	    this.debug.geometry = geometry;
330	  }
331	
332	  /**
333	   * 眠っている (止まって計算を省かれている) 物は、剛体を持たない当たり判定が動いてきても起きない。
334	   * 現実の物が押しのけられるよう、重なった物は起こす。
335	   */
336	  private wakeTouching(): void {
337	    const collider = this.collider;
338	    if (!collider) return;
339	    this.app.physics.world.intersectionsWithShape(
340	      collider.translation(),
341	      IDENTITY,
342	      collider.shape,
343	      (other) => {
344	        const body = other.parent();
345	        if (body?.isSleeping()) body.wakeUp();
346	        return true;
347	      },
348	      RAPIER.QueryFilterFlags.ONLY_DYNAMIC,
349	    );
350	  }
351	}
