199	/**
200	 * 現実の物や自分の手で、仮想物体を隠す (depth-sensing)。方式が 2 つある。
201	 *
202	 * くっきり: 現実の深度を、仮想物体より先に深度バッファへ書いておく。three.js 標準の仕組みで、
203	 *   WebXRManager が毎フレーム深度テクスチャを受け取り、それを書くだけのメッシュを最初に描く。
204	 *   以降の仮想物体は、現実の面より奥にある画素が深度テストで落ちる。
205	 *   ここではそのメッシュのシェーダーを、センサーの誤差のぶん奥へずらして書くものに差し替えている。
206	 *   画素ごとに「見える / 見えない」の二択なので、深度が揺れる所ではチラつく。
207	 *
208	 * ぼかし: 深度バッファには書かず、各マテリアルのシェーダーの中で現実の深度と比べ、
209	 *   周囲の判定の平均に応じて薄くする。輪郭がなめらかになり、深度の揺れは濃淡の揺れに和らぐ。
210	 *   そのぶん、仮想物体を描く画素ごとに深度を何度も読むので重い。
211	 */
212	export class Occlusion implements Feature {
213	  readonly name = 'occlusion';
214	  enabled = true;
215	  /** true なら「ぼかし」、false なら「くっきり」 */
216	  soft = true;
217	  /** 深度データが届いているか */
218	  active = false;
219	
220	  private patched: THREE.Mesh | null = null;
221	  private material: THREE.ShaderMaterial | null = null;
222	
223	  constructor(private readonly app: App) {
224	    installSoftOcclusion();
225	    app.menu.addToggle(
226	      '遮蔽',
227	      () => this.enabled,
228	      (value) => (this.enabled = value),
229	    );
230	    app.menu.addToggle(
231	      '遮蔽をぼかす',
232	      () => this.soft,
233	      (value) => (this.soft = value),
234	    );
235	  }
236	
237	  update(): void {
238	    const xr = this.app.renderer.xr;
239	    // 深度データが一度も届いていない間は null。
240	    const mesh = xr.getDepthSensingMesh();
241	    const texture = xr.getDepthTexture();
242	    this.active = mesh !== null && texture !== null;
243	    softUniforms.xrDepthTexture.value = texture;
244	    softUniforms.xrOcclusionStrength.value = this.active && this.enabled && this.soft ? 1 : 0;
245	    if (!mesh) return;
246	    mesh.visible = this.enabled && !this.soft;
247	    if (mesh !== this.patched) this.patch(mesh);
248	
249	    // 深度テクスチャは描画と同じ near / far で作られている (three.js がカメラ側を合わせる)。
250	    // 両目で共通なので、片目の射影行列から係数を取ればよい。
251	    const eye = xr.getCamera().cameras[0];
252	    if (!eye || !this.material) return;
253	    const a = eye.projectionMatrix.elements[10];
254	    const b = eye.projectionMatrix.elements[14];
255	    this.material.uniforms.projectionA.value = a;
256	    this.material.uniforms.projectionB.value = b;
257	    softUniforms.xrProjection.value.set(a, b);
258	    softUniforms.xrDepthSize.value.set(eye.viewport.z, eye.viewport.w);
259	  }
260	
261	  end(): void {
262	    this.active = false;
263	    this.patched = null;
264	    this.material?.dispose();
265	    this.material = null;
266	    softUniforms.xrDepthTexture.value = null;
267	    softUniforms.xrOcclusionStrength.value = 0;
268	  }
269	
270	  /** three.js が作ったメッシュのマテリアルを差し替える。テクスチャなどの値は元のものを引き継ぐ。 */
271	  private patch(mesh: THREE.Mesh): void {
272	    const original = mesh.material as THREE.ShaderMaterial;
273	    this.material?.dispose();
274	    this.material = new THREE.ShaderMaterial({
275	      vertexShader: VERTEX_SHADER,
276	      fragmentShader: FRAGMENT_SHADER,
277	      defines: {
278	        ABSOLUTE_BIAS: ABSOLUTE_BIAS.toFixed(4),
279	        RELATIVE_BIAS: RELATIVE_BIAS.toFixed(4),
280	        TAP_RADIUS: TAP_RADIUS.toFixed(1),
281	      },
282	      uniforms: {
283	        depthColor: original.uniforms.depthColor,
284	        depthWidth: original.uniforms.depthWidth,
285	        depthHeight: original.uniforms.depthHeight,
286	        projectionA: { value: -1 },
287	        projectionB: { value: -0.1 },
288	      },
289	    });
290	    mesh.material = this.material;
291	    original.dispose();
292	    this.patched = mesh;
293	  }
294	}
